from blib2to3.pgen2 import literals


def test_test_round_trips_all_byte_values(monkeypatch, capsys):
    original_eval_string = literals.evalString
    calls = []

    def recording_eval_string(value):
        calls.append(value)
        return original_eval_string(value)

    monkeypatch.setattr(literals, "evalString", recording_eval_string)

    literals.test()

    assert calls == [repr(chr(i)) for i in range(256)]
    assert capsys.readouterr().out == ""


def test_test_reports_a_mismatched_value(monkeypatch, capsys):
    original_eval_string = literals.evalString
    mismatched_string = repr(chr(0))

    def mismatching_eval_string(value):
        if value == mismatched_string:
            return "wrong"
        return original_eval_string(value)

    monkeypatch.setattr(literals, "evalString", mismatching_eval_string)

    literals.test()

    assert capsys.readouterr().out == "0 \x00 '\\x00' wrong\n"
